// Bezel Reflect - Native Metal overlay with procedural reflections and tint
#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint   FrameCount;
    float  reflect_strength; // 0..1
    float  gloss;            // 0..1 controls sharpness of reflection streaks
    float  tint_r;           // 0..1
    float  tint_g;           // 0..1
    float  tint_b;           // 0..1
    float  vignette;         // 0..2
    float  gamma;            // 0.4..3.0
};

struct VertexIn { float4 position [[attribute(0)]]; float2 texCoord [[attribute(1)]]; };
struct VertexOut { float4 position [[position]]; float2 texCoord; };

vertex VertexOut main0(VertexIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VertexOut out; out.position = u.MVP * in.position; out.texCoord = in.texCoord; return out;
}

static inline float hash21(float2 p){ return fract(sin(dot(p, float2(12.9898,78.233))) * 43758.5453); }
static inline float2 noise2(float2 p){ float a = hash21(p); float b = hash21(p+37.0); return float2(a,b)*2.0-1.0; }

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &u [[buffer(0)]]
) {
    constexpr sampler smp(mag_filter::linear, min_filter::linear, address::clamp_to_edge);
    float2 uv = in.texCoord;

    // Base color (screen)
    float3 base = sourceTexture.sample(smp, uv).rgb;

    // Procedural bezel mask: soften edges to simulate glass edge falloff
    float2 p = uv * 2.0 - 1.0;
    float edge = smoothstep(1.0, 0.7, max(abs(p.x), abs(p.y)));

    // Simple normal from radial gradient + noise, scaled by gloss
    float r = length(p);
    float3 n = normalize(float3(p.x, p.y, 1.0 - r));
    float2 nJit = noise2(p * 24.0 + float(u.FrameCount)*0.01) * (0.15 + 0.35 * (1.0 - u.gloss));
    n = normalize(n + float3(nJit, 0.0));

    // View direction assumed camera at z=-1 looking along +z
    float3 v = normalize(float3(0.0,0.0,1.0));
    float3 rdir = reflect(-v, n);

    // Procedural reflection sample: warp into screen UV space for fake env
    float2 ruv = rdir.xy * 0.5 + 0.5;
    // Add a thin streak that shifts with time and gloss
    float t = float(u.FrameCount) * (0.004 + 0.01 * u.gloss);
    ruv += float2(0.15 * sin(t + r*4.0), 0.08 * cos(t*1.3 + p.x*6.0)) * (0.4 + 0.6*u.gloss);
    float3 refl = sourceTexture.sample(smp, clamp(ruv, 0.0, 1.0)).rgb;

    // Tint
    float3 tint = float3(u.tint_r, u.tint_g, u.tint_b);
    refl = mix(refl, refl * tint, 0.5);

    // Blend reflection over base using edge falloff and reflect_strength
    float reflMask = edge * (0.6 + 0.4 * smoothstep(0.5, 1.0, r));
    float3 col = mix(base, mix(base, refl, 0.6), u.reflect_strength * reflMask);

    // Vignette
    float vig = pow(clamp(1.0 - r, 0.0, 1.0), 1.0 + u.vignette);
    col *= mix(1.0, vig, 0.6);

    // Gamma
    col = pow(max(col, 0.0), float3(1.0/max(u.gamma, 0.001)));

    return float4(saturate(col), 1.0);
}

